CREATE TABLE IF NOT EXISTS "LoaiBien" (
    "Id" INTEGER PRIMARY KEY,
    "Ten" VARCHAR(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS "TapDuLieu" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Ten" VARCHAR(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS "Mau" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DuongDanAnh" VARCHAR(500) NOT NULL,
    "DoPhanGiai" VARCHAR(50),
    "TapDuLieuId" INTEGER NOT NULL,
    CONSTRAINT "FK_Mau_TapDuLieu" FOREIGN KEY ("TapDuLieuId") REFERENCES "TapDuLieu" ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "KhungNhanDang" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "XCenter" REAL,
    "YCenter" REAL,
    "W" REAL,
    "H" REAL,
    "MauId" INTEGER NOT NULL,
    "BienId" INTEGER NOT NULL,
    CONSTRAINT "FK_KhungNhanDang_Mau" FOREIGN KEY ("MauId") REFERENCES "Mau" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_KhungNhanDang_LoaiBien" FOREIGN KEY ("BienId") REFERENCES "LoaiBien" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_Mau_TapDuLieuId" ON "Mau" ("TapDuLieuId");
CREATE INDEX IF NOT EXISTS "IX_KhungNhanDang_MauId" ON "KhungNhanDang" ("MauId");
CREATE INDEX IF NOT EXISTS "IX_KhungNhanDang_BienId" ON "KhungNhanDang" ("BienId");

