SELECT setval(
    pg_get_serial_sequence('"TapDuLieu"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "TapDuLieu"), 1), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('"Mau"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "Mau"), 1), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('"KhungNhanDang"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "KhungNhanDang"), 1), 1),
    true
);
